export function isEmoji(cp: number): boolean { return inRanges(EmojiRanges, cp); }
export function isPresentation(cp: number): boolean { return inRanges(PresentationRanges, cp); }
export function isModifier(cp: number): boolean { return inRanges(ModifierRanges, cp); }
export function isModifierBase(cp: number): boolean { return inRanges(ModifierBaseRanges, cp); }
export function isExtendedPictographic(cp: number): boolean { return inRanges(ExtendedPictographicRanges, cp); }
export function isExtend(cp: number): boolean { return inRanges(ExtendRanges, cp); }
export function isSpacingMark(cp: number): boolean { return inRanges(SpacingMarkRanges, cp); }
export function isRegional(cp: number): boolean { return inRanges(RegionalRanges, cp); }

export function sequenceKind(points: readonly number[], start: number, end: number): number {
  let state = 0;
  for (let i = start; i < end; i++) {
    const at = state * 3; let low = unit(States, at), high = low + unit(States, at + 1) - 1, next = -1;
    while (low <= high) {
      const mid = Math.floor(low + (high - low) / 2), p = mid * 3, cp = scalar(Edges, p);
      if (points[i] < cp) high = mid - 1;
      else if (points[i] > cp) low = mid + 1;
      else { next = unit(Edges, p + 2); break; }
    }
    if (next < 0) return 0;
    state = next;
  }
  return unit(States, state * 3 + 2);
}
